/*
 * Concept 9: Ocean Wave Energy Converter
 * One scene | 25 seconds | seamless loop | pure Canvas 2D.
 * Render size: 3840 x 2160 (16:9); scales uniformly to FHD and 2K.
 * Suggested export frame rate: 60 fps.
 * Required encoder video bitrate: 100000000 bits per second or higher.
 * Bitrate must be configured in the host video encoder; draw() renders pixels only.
 * No external assets, DOM, imports, dependencies, glow, or stroked paths.
 */
function draw(ctx, time, width, height) {
  ctx.fillStyle = '#00FF00';
  ctx.fillRect(0, 0, width, height);

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowColor = 'transparent';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.filter = 'none';
  ctx.fillStyle = '#00FF00';
  ctx.fillRect(0, 0, width, height);

  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const scale = Math.min(width / 1920, height / 1080, minSide / 1080);
  const TAU = Math.PI * 2;
  const phase = TAU * (currentScene + sceneProgress);
  const P = {
    navy: '#182B49',
    blue: '#285CCD',
    cobalt: '#387CF2',
    pale: '#B7D1FB',
    ice: '#E5EDFA',
    white: '#FAF7EF',
    amber: '#FFBB59',
    coral: '#F17A64',
    gray: '#C9D2DF'
  };

  ctx.translate(width * 0.5, height * 0.5);
  ctx.scale(scale, scale);
  ctx.translate(-960, -540);

  function roundedPath(x, y, w, h, radius) {
    const r = Math.max(0, Math.min(radius, w * 0.5, h * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }

  function box(x, y, w, h, radius, color) {
    roundedPath(x, y, w, h, radius);
    ctx.fillStyle = color;
    ctx.fill();
  }

  function circle(x, y, radius, color) {
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, TAU);
    ctx.fillStyle = color;
    ctx.fill();
  }

  function polygon(points, color) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) {
      ctx.lineTo(points[i][0], points[i][1]);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
  }

  function text(value, x, y, size, color, align, weight, maxWidth) {
    ctx.save();
    ctx.textAlign = align || 'left';
    ctx.textBaseline = 'alphabetic';
    let fontSize = size;
    ctx.font = (weight || 600) + ' ' + fontSize + 'px Arial, Helvetica, sans-serif';
    if (maxWidth && ctx.measureText(value).width > maxWidth) {
      fontSize *= maxWidth / ctx.measureText(value).width;
      ctx.font = (weight || 600) + ' ' + fontSize + 'px Arial, Helvetica, sans-serif';
    }
    ctx.fillStyle = color;
    ctx.fillText(value, x, y);
    ctx.restore();
  }

  function bolt(x, y, size, color) {
    polygon([
      [x + size * 0.12, y - size * 0.55],
      [x - size * 0.39, y + size * 0.06],
      [x - size * 0.04, y + size * 0.06],
      [x - size * 0.15, y + size * 0.55],
      [x + size * 0.42, y - size * 0.13],
      [x + size * 0.08, y - size * 0.13]
    ], color);
  }

  // Rounded conduits are closed filled geometry. No stroked paths are used.
  function makeRoute(points, cornerRadius) {
    const samples = [points[0].slice()];
    let current = points[0].slice();

    function appendLine(end) {
      const start = current;
      const steps = Math.max(1, Math.ceil(Math.hypot(end[0] - start[0], end[1] - start[1]) / 10));
      for (let n = 1; n <= steps; n++) {
        const u = n / steps;
        samples.push([start[0] + (end[0] - start[0]) * u, start[1] + (end[1] - start[1]) * u]);
      }
      current = end.slice();
    }

    for (let i = 1; i < points.length - 1; i++) {
      const a = points[i - 1];
      const b = points[i];
      const c = points[i + 1];
      const before = Math.hypot(a[0] - b[0], a[1] - b[1]);
      const after = Math.hypot(c[0] - b[0], c[1] - b[1]);
      const cut = Math.min(cornerRadius, before * 0.42, after * 0.42);
      const entry = [b[0] + (a[0] - b[0]) * cut / before, b[1] + (a[1] - b[1]) * cut / before];
      const exit = [b[0] + (c[0] - b[0]) * cut / after, b[1] + (c[1] - b[1]) * cut / after];
      appendLine(entry);
      for (let n = 1; n <= 12; n++) {
        const u = n / 12;
        const v = 1 - u;
        samples.push([v * v * entry[0] + 2 * v * u * b[0] + u * u * exit[0], v * v * entry[1] + 2 * v * u * b[1] + u * u * exit[1]]);
      }
      current = exit.slice();
    }
    appendLine(points[points.length - 1]);

    const distance = [0];
    for (let i = 1; i < samples.length; i++) {
      distance.push(distance[i - 1] + Math.hypot(samples[i][0] - samples[i - 1][0], samples[i][1] - samples[i - 1][1]));
    }
    return { samples: samples, distance: distance, length: distance[distance.length - 1] };
  }

  function routePath(route, thickness) {
    const a = route.samples;
    const normals = [];
    for (let i = 0; i < a.length; i++) {
      const previous = a[Math.max(0, i - 1)];
      const next = a[Math.min(a.length - 1, i + 1)];
      const dx = next[0] - previous[0];
      const dy = next[1] - previous[1];
      const magnitude = Math.hypot(dx, dy) || 1;
      normals.push([-dy / magnitude * thickness * 0.5, dx / magnitude * thickness * 0.5]);
    }
    ctx.beginPath();
    ctx.moveTo(a[0][0] + normals[0][0], a[0][1] + normals[0][1]);
    for (let i = 1; i < a.length; i++) {
      ctx.lineTo(a[i][0] + normals[i][0], a[i][1] + normals[i][1]);
    }
    for (let i = a.length - 1; i >= 0; i--) {
      ctx.lineTo(a[i][0] - normals[i][0], a[i][1] - normals[i][1]);
    }
    ctx.closePath();
  }

  function routePose(route, distance) {
    const target = Math.max(0, Math.min(route.length, distance));
    let low = 1;
    let high = route.distance.length - 1;
    while (low < high) {
      const mid = (low + high) >> 1;
      if (route.distance[mid] < target) low = mid + 1;
      else high = mid;
    }
    const i = low;
    const previous = route.samples[i - 1];
    const next = route.samples[i];
    const span = route.distance[i] - route.distance[i - 1];
    const u = span > 0 ? (target - route.distance[i - 1]) / span : 0;
    return {
      x: previous[0] + (next[0] - previous[0]) * u,
      y: previous[1] + (next[1] - previous[1]) * u,
      angle: Math.atan2(next[1] - previous[1], next[0] - previous[0])
    };
  }

  function conduit(route, thickness, motion, spacing, packetColor) {
    routePath(route, thickness);
    ctx.fillStyle = P.navy;
    ctx.fill();
    ctx.save();
    routePath(route, thickness);
    ctx.clip();
    const count = Math.max(1, Math.round(route.length / spacing));
    const gap = route.length / count;
    const travel = ((motion % 1) + 1) % 1;
    for (let i = 0; i < count; i++) {
      const pose = routePose(route, (i + travel) * gap);
      ctx.save();
      ctx.translate(pose.x, pose.y);
      ctx.rotate(pose.angle);
      box(-10, -3.5, 20, 7, 3.5, packetColor || P.amber);
      ctx.restore();
    }
    ctx.restore();
  }

  function waveBand(x, y, w, amplitude, thickness, wavePhase, cycles, color, tapered) {
    const count = 64;
    ctx.beginPath();
    for (let i = 0; i <= count; i++) {
      const u = i / count;
      const taper = tapered ? Math.pow(Math.sin(Math.PI * u), 0.7) : 1;
      const py = y + Math.sin(u * TAU * cycles - wavePhase) * amplitude;
      const edge = py - thickness * 0.5 * taper;
      if (i === 0) ctx.moveTo(x + u * w, edge);
      else ctx.lineTo(x + u * w, edge);
    }
    for (let i = count; i >= 0; i--) {
      const u = i / count;
      const taper = tapered ? Math.pow(Math.sin(Math.PI * u), 0.7) : 1;
      const py = y + Math.sin(u * TAU * cycles - wavePhase) * amplitude;
      ctx.lineTo(x + u * w, py + thickness * 0.5 * taper);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
  }

  function stageLabel(x, main, detail, maximum) {
    text(main, x, 914, 21, P.navy, 'center', 700, maximum);
    text(detail, x, 946, 15, P.navy, 'center', 500, maximum);
  }

  function meterBars(x, bottom, count, spacing, width, height, power, offset, color) {
    for (let i = 0; i < count; i++) {
      const detail = 0.76 + 0.24 * Math.sin(phase * 6 - i * 0.48 + offset);
      const h = 8 + height * power * detail;
      box(x + i * spacing, bottom - h, width, h, Math.min(3, width / 2), color);
    }
  }

  function solarPanel(x, y, w, h, production) {
    box(x, y, w, h, 7, P.navy);
    const gap = 5;
    const cw = (w - 16 - gap * 3) / 4;
    const ch = (h - 16 - gap) / 2;
    for (let row = 0; row < 2; row++) {
      for (let col = 0; col < 4; col++) {
        const px = x + 8 + col * (cw + gap);
        const py = y + 8 + row * (ch + gap);
        box(px, py, cw, ch, 2, P.blue);
        box(px + 5, py + 4, cw - 10, 2.5, 1.25, P.pale);
        const fill = (cw - 10) * (0.36 + production * 0.5);
        box(px + 5, py + ch - 6, fill, 2.5, 1.25, P.amber);
      }
    }
  }

  function districtWindow(x, y, w, h, demand, offset) {
    box(x, y, w, h, 4, P.navy);
    box(x + 5, y + 5, w - 10, h - 10, 2, P.blue);
    box(x + 8, y + 9, w - 16, 3, 1.5, P.pale);
    const bar = 5 + (h - 28) * (0.28 + demand * 0.4);
    box(x + 9, y + h - 9 - bar, w - 18, bar, 2, P.pale);
    // A small opaque load indicator, with no opacity or color interpolation.
    const indicator = 4 + 3 * (0.5 + 0.5 * Math.sin(phase * 2 + offset));
    box(x + 9, y + h - 8, indicator, 2, 1, P.amber);
  }

  text('OCEAN WAVE ENERGY', 150, 156, 48, P.navy, 'left', 700, 1100);
  text('POINT ABSORBERS  /  SYNCHRONIZED HEAVE  /  CLEAN OUTPUT', 152, 192, 18, P.navy, 'left', 600, 1190);

  const oceanX = 150;
  const oceanW = 1140;
  const oceanBottom = 820;
  const stations = [355, 730, 1105];
  const stationColors = [P.amber, P.coral, P.amber];
  const waveAngle = phase * 3 + 0.19;
  function surfaceY(x) {
    return 533 + 19 * Math.sin((x - oceanX) / oceanW * TAU * 1.8 - waveAngle);
  }
  function stationPower(x) {
    const theta = (x - oceanX) / oceanW * TAU * 1.8 - waveAngle;
    const velocity = Math.cos(theta);
    return 0.34 + 0.66 * velocity * velocity;
  }
  const totalPower = (stationPower(stations[0]) + stationPower(stations[1]) + stationPower(stations[2])) / 3;

  // The electrical collection bus sits below the water cutaway. Each endpoint
  // is buried in a casing or junction so periodic packets cannot visibly pop.
  const collection = makeRoute([[344, 864], [1370, 864], [1370, 734], [1466, 734]], 30);
  conduit(collection, 15, sceneProgress * 12, 75, P.amber);
  for (let i = 0; i < stations.length; i++) {
    const branch = makeRoute([[stations[i], 803], [stations[i], 864]], 16);
    conduit(branch, 15, sceneProgress * 12 + i / 3, 58, stationColors[i]);
    circle(stations[i], 864, 14, P.navy);
    circle(stations[i], 864, 5, stationColors[i]);
  }

  // A contained ocean illustration keeps every pixel outside it chroma green.
  // The same sample positions and analytic function define the surface and the
  // buoy attachment. Explicit station samples guarantee exact vertical contact.
  const surfaceSamples = [];
  for (let i = 0; i <= 120; i++) surfaceSamples.push(oceanX + oceanW * i / 120);
  for (let i = 0; i < stations.length; i++) surfaceSamples.push(stations[i]);
  surfaceSamples.sort(function (a, b) { return a - b; });
  ctx.save();
  roundedPath(oceanX, 450, oceanW, oceanBottom - 450, 20);
  ctx.clip();
  ctx.beginPath();
  ctx.moveTo(surfaceSamples[0], surfaceY(surfaceSamples[0]));
  for (let i = 1; i < surfaceSamples.length; i++) ctx.lineTo(surfaceSamples[i], surfaceY(surfaceSamples[i]));
  ctx.lineTo(oceanX + oceanW, oceanBottom);
  ctx.lineTo(oceanX, oceanBottom);
  ctx.closePath();
  ctx.fillStyle = P.cobalt;
  ctx.fill();

  ctx.beginPath();
  ctx.moveTo(oceanX, 681 + 7 * Math.sin(-waveAngle + 0.7));
  for (let i = 1; i <= 100; i++) {
    const u = i / 100;
    ctx.lineTo(oceanX + oceanW * u, 681 + 7 * Math.sin(u * TAU * 1.8 - waveAngle + 0.7));
  }
  ctx.lineTo(oceanX + oceanW, oceanBottom);
  ctx.lineTo(oceanX, oceanBottom);
  ctx.closePath();
  ctx.fillStyle = P.blue;
  ctx.fill();

  ctx.beginPath();
  ctx.moveTo(surfaceSamples[0], surfaceY(surfaceSamples[0]));
  for (let i = 1; i < surfaceSamples.length; i++) ctx.lineTo(surfaceSamples[i], surfaceY(surfaceSamples[i]));
  for (let i = surfaceSamples.length - 1; i >= 0; i--) ctx.lineTo(surfaceSamples[i], surfaceY(surfaceSamples[i]) + 7);
  ctx.closePath();
  ctx.fillStyle = P.pale;
  ctx.fill();
  waveBand(175, 617, 1090, 7, 4, waveAngle - 0.8, 2.2, P.pale, true);
  waveBand(175, 744, 1090, 5, 3, waveAngle + 0.7, 2.2, P.cobalt, true);
  box(oceanX, 807, oceanW, 13, 0, P.navy);
  ctx.restore();

  for (let i = 0; i < stations.length; i++) {
    const x = stations[i];
    const y = surfaceY(x);
    const power = stationPower(x);
    const color = stationColors[i];

    // Fixed telemetry, separate from the largest possible buoy excursion.
    box(x - 100, 295, 200, 94, 12, P.white);
    text('ABSORBER 0' + (i + 1), x - 79, 325, 17, P.navy, 'left', 700, 150);
    circle(x + 77, 319, 5, color);
    text('HEAVE', x - 79, 371, 12, P.navy, 'left', 600, 50);
    meterBars(x - 16, 371, 7, 13, 7, 28, power, i * 0.7, color);

    // This is a guided vertical point absorber, not a freely pitching boat.
    // The piston changes exposed length; the float itself never scales or tilts.
    box(x - 8, y + 14, 16, 711 - (y + 14), 4, P.gray);
    box(x - 3, y + 14, 6, 711 - (y + 14), 2, P.white);
    box(x - 57, 790, 114, 17, 5, P.ice);
    box(x - 42, 666, 84, 124, 12, P.white);
    box(x - 42, 666, 84, 29, 12, P.navy);
    box(x - 42, 683, 84, 12, 0, P.navy);
    box(x - 16, 657, 32, 17, 5, P.navy);
    box(x - 25, 710, 50, 47, 6, P.ice);
    bolt(x, 733, 29, color);
    for (let vent = 0; vent < 3; vent++) box(x - 24 + vent * 19, 773, 10, 4, 2, P.gray);
    circle(x, 806, 12, P.navy);
    circle(x, 806, 5, color);

    // One filled hull is translated rigidly by the exact local surface height.
    ctx.save();
    ctx.translate(x, y);
    box(-3, -84, 6, 45, 2, P.navy);
    box(-12, -90, 24, 9, 4, color);
    ctx.beginPath();
    ctx.moveTo(-77, -46);
    ctx.lineTo(77, -46);
    ctx.quadraticCurveTo(94, -46, 91, -27);
    ctx.lineTo(81, 14);
    ctx.quadraticCurveTo(78, 27, 63, 27);
    ctx.lineTo(-63, 27);
    ctx.quadraticCurveTo(-78, 27, -81, 14);
    ctx.lineTo(-91, -27);
    ctx.quadraticCurveTo(-94, -46, -77, -46);
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
    box(-79, -48, 158, 13, 5, P.white);
    box(-37, -21, 74, 22, 6, P.navy);
    box(-25, -13, 50 * power, 6, 3, P.white);
    box(-55, 12, 110, 5, 2.5, P.navy);
    ctx.restore();
  }

  // A separate fixed conversion cabinet receives the collected marine power.
  box(1434, 710, 33, 48, 8, P.navy);
  box(1450, 326, 320, 494, 23, P.white);
  box(1450, 326, 320, 74, 23, P.navy);
  box(1450, 376, 320, 24, 0, P.navy);
  text('POWER MODULE', 1610, 371, 25, P.white, 'center', 700, 270);
  text('GENERATOR', 1610, 438, 16, P.navy, 'center', 700, 254);
  circle(1610, 521, 65, P.navy);
  circle(1610, 521, 53, P.pale);
  ctx.save();
  ctx.translate(1610, 521);
  ctx.rotate(phase * 4);
  for (let blade = 0; blade < 8; blade++) {
    ctx.save();
    ctx.rotate(blade * TAU / 8);
    box(-7, -44, 14, 22, 4, P.blue);
    ctx.restore();
  }
  ctx.restore();
  circle(1610, 521, 21, P.amber);
  bolt(1610, 521, 22, P.navy);
  box(1480, 612, 260, 105, 12, P.ice);
  text('COLLECTED POWER', 1497, 637, 14, P.navy, 'left', 700, 224);
  meterBars(1499, 698, 10, 24, 13, 47, totalPower, 0.4, P.blue);
  text('CONTINUOUS OUTPUT', 1610, 761, 17, P.navy, 'center', 700, 270);
  for (let i = 0; i < 7; i++) box(1495 + i * 34, 789, 25, 5, 2.5, P.gray);

  stageLabel(355, 'WAVE 01', 'SURFACE-TRACKED HEAVE', 250);
  stageLabel(730, 'WAVE 02', 'SURFACE-TRACKED HEAVE', 250);
  stageLabel(1105, 'WAVE 03', 'SURFACE-TRACKED HEAVE', 250);
  stageLabel(1610, 'POWER EXPORT', 'CONTINUOUS CONVERSION', 320);
  ctx.restore();
}

/*
 * Concept 10: Smart Renewable Energy District
 * One scene | 25 seconds | seamless loop | pure Canvas 2D.
 * Render size: 3840 x 2160 (16:9); scales uniformly to FHD and 2K.
 * Suggested export frame rate: 60 fps.
 * Required encoder video bitrate: 100000000 bits per second or higher.
 * Bitrate must be configured in the host video encoder; draw() renders pixels only.
 * No external assets, DOM, imports, dependencies, glow, or stroked paths.
 */
function draw(ctx, time, width, height) {
  ctx.fillStyle = '#00FF00';
  ctx.fillRect(0, 0, width, height);

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowColor = 'transparent';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.filter = 'none';
  ctx.fillStyle = '#00FF00';
  ctx.fillRect(0, 0, width, height);

  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const scale = Math.min(width / 1920, height / 1080, minSide / 1080);
  const TAU = Math.PI * 2;
  const phase = TAU * (currentScene + sceneProgress);
  const P = {
    navy: '#182B49',
    blue: '#285CCD',
    cobalt: '#387CF2',
    pale: '#B7D1FB',
    ice: '#E5EDFA',
    white: '#FAF7EF',
    amber: '#FFBB59',
    coral: '#F17A64',
    gray: '#C9D2DF'
  };

  ctx.translate(width * 0.5, height * 0.5);
  ctx.scale(scale, scale);
  ctx.translate(-960, -540);

  function roundedPath(x, y, w, h, radius) {
    const r = Math.max(0, Math.min(radius, w * 0.5, h * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }

  function box(x, y, w, h, radius, color) {
    roundedPath(x, y, w, h, radius);
    ctx.fillStyle = color;
    ctx.fill();
  }

  function circle(x, y, radius, color) {
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, TAU);
    ctx.fillStyle = color;
    ctx.fill();
  }

  function polygon(points, color) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) {
      ctx.lineTo(points[i][0], points[i][1]);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
  }

  function text(value, x, y, size, color, align, weight, maxWidth) {
    ctx.save();
    ctx.textAlign = align || 'left';
    ctx.textBaseline = 'alphabetic';
    let fontSize = size;
    ctx.font = (weight || 600) + ' ' + fontSize + 'px Arial, Helvetica, sans-serif';
    if (maxWidth && ctx.measureText(value).width > maxWidth) {
      fontSize *= maxWidth / ctx.measureText(value).width;
      ctx.font = (weight || 600) + ' ' + fontSize + 'px Arial, Helvetica, sans-serif';
    }
    ctx.fillStyle = color;
    ctx.fillText(value, x, y);
    ctx.restore();
  }

  function bolt(x, y, size, color) {
    polygon([
      [x + size * 0.12, y - size * 0.55],
      [x - size * 0.39, y + size * 0.06],
      [x - size * 0.04, y + size * 0.06],
      [x - size * 0.15, y + size * 0.55],
      [x + size * 0.42, y - size * 0.13],
      [x + size * 0.08, y - size * 0.13]
    ], color);
  }

  // Rounded conduits are closed filled geometry. No stroked paths are used.
  function makeRoute(points, cornerRadius) {
    const samples = [points[0].slice()];
    let current = points[0].slice();

    function appendLine(end) {
      const start = current;
      const steps = Math.max(1, Math.ceil(Math.hypot(end[0] - start[0], end[1] - start[1]) / 10));
      for (let n = 1; n <= steps; n++) {
        const u = n / steps;
        samples.push([start[0] + (end[0] - start[0]) * u, start[1] + (end[1] - start[1]) * u]);
      }
      current = end.slice();
    }

    for (let i = 1; i < points.length - 1; i++) {
      const a = points[i - 1];
      const b = points[i];
      const c = points[i + 1];
      const before = Math.hypot(a[0] - b[0], a[1] - b[1]);
      const after = Math.hypot(c[0] - b[0], c[1] - b[1]);
      const cut = Math.min(cornerRadius, before * 0.42, after * 0.42);
      const entry = [b[0] + (a[0] - b[0]) * cut / before, b[1] + (a[1] - b[1]) * cut / before];
      const exit = [b[0] + (c[0] - b[0]) * cut / after, b[1] + (c[1] - b[1]) * cut / after];
      appendLine(entry);
      for (let n = 1; n <= 12; n++) {
        const u = n / 12;
        const v = 1 - u;
        samples.push([v * v * entry[0] + 2 * v * u * b[0] + u * u * exit[0], v * v * entry[1] + 2 * v * u * b[1] + u * u * exit[1]]);
      }
      current = exit.slice();
    }
    appendLine(points[points.length - 1]);

    const distance = [0];
    for (let i = 1; i < samples.length; i++) {
      distance.push(distance[i - 1] + Math.hypot(samples[i][0] - samples[i - 1][0], samples[i][1] - samples[i - 1][1]));
    }
    return { samples: samples, distance: distance, length: distance[distance.length - 1] };
  }

  function routePath(route, thickness) {
    const a = route.samples;
    const normals = [];
    for (let i = 0; i < a.length; i++) {
      const previous = a[Math.max(0, i - 1)];
      const next = a[Math.min(a.length - 1, i + 1)];
      const dx = next[0] - previous[0];
      const dy = next[1] - previous[1];
      const magnitude = Math.hypot(dx, dy) || 1;
      normals.push([-dy / magnitude * thickness * 0.5, dx / magnitude * thickness * 0.5]);
    }
    ctx.beginPath();
    ctx.moveTo(a[0][0] + normals[0][0], a[0][1] + normals[0][1]);
    for (let i = 1; i < a.length; i++) {
      ctx.lineTo(a[i][0] + normals[i][0], a[i][1] + normals[i][1]);
    }
    for (let i = a.length - 1; i >= 0; i--) {
      ctx.lineTo(a[i][0] - normals[i][0], a[i][1] - normals[i][1]);
    }
    ctx.closePath();
  }

  function routePose(route, distance) {
    const target = Math.max(0, Math.min(route.length, distance));
    let low = 1;
    let high = route.distance.length - 1;
    while (low < high) {
      const mid = (low + high) >> 1;
      if (route.distance[mid] < target) low = mid + 1;
      else high = mid;
    }
    const i = low;
    const previous = route.samples[i - 1];
    const next = route.samples[i];
    const span = route.distance[i] - route.distance[i - 1];
    const u = span > 0 ? (target - route.distance[i - 1]) / span : 0;
    return {
      x: previous[0] + (next[0] - previous[0]) * u,
      y: previous[1] + (next[1] - previous[1]) * u,
      angle: Math.atan2(next[1] - previous[1], next[0] - previous[0])
    };
  }

  function conduit(route, thickness, motion, spacing, packetColor) {
    routePath(route, thickness);
    ctx.fillStyle = P.navy;
    ctx.fill();
    ctx.save();
    routePath(route, thickness);
    ctx.clip();
    const count = Math.max(1, Math.round(route.length / spacing));
    const gap = route.length / count;
    const travel = ((motion % 1) + 1) % 1;
    for (let i = 0; i < count; i++) {
      const pose = routePose(route, (i + travel) * gap);
      ctx.save();
      ctx.translate(pose.x, pose.y);
      ctx.rotate(pose.angle);
      box(-10, -3.5, 20, 7, 3.5, packetColor || P.amber);
      ctx.restore();
    }
    ctx.restore();
  }

  function waveBand(x, y, w, amplitude, thickness, wavePhase, cycles, color, tapered) {
    const count = 64;
    ctx.beginPath();
    for (let i = 0; i <= count; i++) {
      const u = i / count;
      const taper = tapered ? Math.pow(Math.sin(Math.PI * u), 0.7) : 1;
      const py = y + Math.sin(u * TAU * cycles - wavePhase) * amplitude;
      const edge = py - thickness * 0.5 * taper;
      if (i === 0) ctx.moveTo(x + u * w, edge);
      else ctx.lineTo(x + u * w, edge);
    }
    for (let i = count; i >= 0; i--) {
      const u = i / count;
      const taper = tapered ? Math.pow(Math.sin(Math.PI * u), 0.7) : 1;
      const py = y + Math.sin(u * TAU * cycles - wavePhase) * amplitude;
      ctx.lineTo(x + u * w, py + thickness * 0.5 * taper);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
  }

  function stageLabel(x, main, detail, maximum) {
    text(main, x, 914, 21, P.navy, 'center', 700, maximum);
    text(detail, x, 946, 15, P.navy, 'center', 500, maximum);
  }

  function meterBars(x, bottom, count, spacing, width, height, power, offset, color) {
    for (let i = 0; i < count; i++) {
      const detail = 0.76 + 0.24 * Math.sin(phase * 6 - i * 0.48 + offset);
      const h = 8 + height * power * detail;
      box(x + i * spacing, bottom - h, width, h, Math.min(3, width / 2), color);
    }
  }

  function solarPanel(x, y, w, h, production) {
    box(x, y, w, h, 7, P.navy);
    const gap = 5;
    const cw = (w - 16 - gap * 3) / 4;
    const ch = (h - 16 - gap) / 2;
    for (let row = 0; row < 2; row++) {
