        const px = x + 8 + col * (cw + gap);
        const py = y + 8 + row * (ch + gap);
        box(px, py, cw, ch, 2, P.blue);
        box(px + 5, py + 4, cw - 10, 2.5, 1.25, P.pale);
        const fill = (cw - 10) * (0.36 + production * 0.5);
        box(px + 5, py + ch - 6, fill, 2.5, 1.25, P.amber);
      }
    }
  }

  function districtWindow(x, y, w, h, demand, offset) {
    box(x, y, w, h, 4, P.navy);
    box(x + 5, y + 5, w - 10, h - 10, 2, P.blue);
    box(x + 8, y + 9, w - 16, 3, 1.5, P.pale);
    const bar = 5 + (h - 28) * (0.28 + demand * 0.4);
    box(x + 9, y + h - 9 - bar, w - 18, bar, 2, P.pale);
    // A small opaque load indicator, with no opacity or color interpolation.
    const indicator = 4 + 3 * (0.5 + 0.5 * Math.sin(phase * 2 + offset));
    box(x + 9, y + h - 8, indicator, 2, 1, P.amber);
  }

  text('SMART RENEWABLE DISTRICT', 150, 156, 48, P.navy, 'left', 700, 1420);
  text('ROOFTOP GENERATION  /  LOCAL DEMAND  /  SHARED ENERGY STORAGE', 152, 192, 18, P.navy, 'left', 600, 1370);

  // Three equal solar contributions have phased variation that sums to a
  // constant supply. Demand plus the battery charge rate equals that supply.
  const production = [];
  for (let i = 0; i < 3; i++) production.push(0.63 + 0.06 * Math.sin(phase * 3 + i * TAU / 3));
  const supply = production[0] + production[1] + production[2];
  const chargeRate = 0.21 * Math.cos(phase * 2);
  const demand = supply - chargeRate;
  const normalizedDemand = demand / 2.3;
  const storedLevel = 0.56 + 0.16 * Math.sin(phase * 2);

  const centers = [300, 660, 1015, 1331, 1635];
  const bus = makeRoute([[1646, 846], [289, 846]], 18);
  conduit(bus, 16, sceneProgress * 14, 72, P.amber);
  for (let i = 0; i < centers.length; i++) {
    let branch;
    let travel;
    if (i === 4) {
      branch = makeRoute([[centers[i], 771], [centers[i], 846]], 16);
      travel = sceneProgress * 14;
    } else {
      branch = makeRoute([[centers[i], 846], [centers[i], 771]], 16);
      // An integrated sinusoid reverses direction only when velocity is zero.
      travel = i === 3 ? 3.2 * Math.sin(phase * 2) : sceneProgress * 14 + i / 3;
    }
    conduit(branch, 16, travel, 65, i === 3 ? P.coral : P.amber);
    circle(centers[i], 846, 14, P.navy);
    circle(centers[i], 846, 5, i === 3 ? P.coral : P.amber);
  }

  // One monitor is a dashboard annotation, not an additional animated scene.
  box(1235, 274, 535, 110, 14, P.white);
  text('COMMUNITY MICROGRID', 1257, 302, 16, P.navy, 'left', 700, 491);
  const chartLabels = ['SUPPLY', 'DEMAND', 'STORED'];
