    text(chartLabels[i], x, 329, 12, P.navy, 'left', 600, 140);
    box(x, 342, 145, 14, 5, P.ice);
    box(x, 342, 145 * chartValues[i], 14, 5, chartColors[i]);
    box(x, 367, 103, 3, 1.5, P.gray);
  }

  // Solar home: the front elevation, roof panels, doors and windows retain
  // their original dimensions. Motion occurs only inside bounded indicators.
  box(188, 482, 11, 25, 3, P.navy);
  box(401, 482, 11, 25, 3, P.navy);
  solarPanel(173, 420, 254, 68, production[0]);
  box(150, 514, 300, 268, 8, P.white);
  box(145, 501, 310, 17, 5, P.navy);
  text('SOLAR HOME', 300, 552, 20, P.navy, 'center', 700, 260);
  districtWindow(174, 578, 86, 72, normalizedDemand, 0.2);
  districtWindow(340, 578, 86, 72, normalizedDemand, 0.8);
  box(276, 643, 48, 139, 5, P.navy);
  box(283, 650, 34, 113, 3, P.blue);
  box(309, 710, 3, 15, 1.5, P.white);
  box(174, 682, 76, 62, 7, P.ice);
  meterBars(185, 732, 4, 15, 8, 32, normalizedDemand, 0.4, P.blue);
  box(350, 682, 71, 62, 7, P.ice);
