  box(150, 782, 300, 14, 4, P.navy);
  box(286, 785, 28, 18, 5, P.navy);

  // Office tower uses an aligned four-by-four window grid with fixed gutters.
  box(548, 357, 10, 27, 3, P.navy);
  box(762, 357, 10, 27, 3, P.navy);
  solarPanel(536, 305, 248, 58, production[1]);
  box(525, 384, 270, 398, 9, P.white);
  box(517, 377, 286, 15, 5, P.navy);
  text('OFFICE', 660, 427, 21, P.navy, 'center', 700, 222);
  for (let row = 0; row < 4; row++) {
