  // The shared storage level and bidirectional packets are phase coherent.
  box(1305, 488, 52, 24, 6, P.navy);
  box(1235, 506, 192, 276, 14, P.white);
  box(1235, 506, 192, 51, 14, P.navy);
  box(1235, 536, 192, 21, 0, P.navy);
  text('STORAGE', 1331, 540, 21, P.white, 'center', 700, 156);
  for (let module = 0; module < 3; module++) {
    const y = 578 + module * 56;
    box(1254, y, 154, 44, 7, P.ice);
