  function energyBars(x, bottom, count, spacing, width, amplitude, offset, color) {
    for (let i = 0; i < count; i++) {
      const h = 11 + amplitude * (0.5 + 0.5 * Math.sin(phase * 2 - i * 0.36 + offset));
      box(x + i * spacing, bottom - h, width, h, 4, color);
