/*
 * Concept 05: Geothermal Heat Exchange Plant
 * One scene | 25 seconds | seamless loop | pure Canvas 2D.
 * Render size: 3840 x 2160 (16:9); scales uniformly to FHD and 2K.
 * Suggested export frame rate: 60 fps.
 * Required encoder video bitrate: 100000000 bits per second or higher.
 * Bitrate must be configured in the host video encoder; draw() renders pixels only.
 * No external assets, DOM, imports, dependencies, glow, or stroked paths.
 */
function draw(ctx, time, width, height) {
  ctx.fillStyle = '#00FF00';
  ctx.fillRect(0, 0, width, height);

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowColor = 'transparent';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.filter = 'none';
  ctx.fillStyle = '#00FF00';
  ctx.fillRect(0, 0, width, height);

  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const scale = Math.min(width / 1920, height / 1080, minSide / 1080);
  const TAU = Math.PI * 2;
  const phase = TAU * (currentScene + sceneProgress);
  const P = {
    navy: '#182B49',
    blue: '#285CCD',
    cobalt: '#387CF2',
    pale: '#B7D1FB',
    ice: '#E5EDFA',
    white: '#FAF7EF',
    amber: '#FFBB59',
    coral: '#F17A64',
    gray: '#C9D2DF',
    terracotta: '#AD6458',
    sand: '#D7B49B'
  };

  ctx.translate(width * 0.5, height * 0.5);
  ctx.scale(scale, scale);
  ctx.translate(-960, -540);

  function roundedPath(x, y, w, h, radius) {
    const r = Math.max(0, Math.min(radius, w * 0.5, h * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }

  function box(x, y, w, h, radius, color) {
    roundedPath(x, y, w, h, radius);
    ctx.fillStyle = color;
    ctx.fill();
  }

  function circle(x, y, radius, color) {
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, TAU);
    ctx.fillStyle = color;
    ctx.fill();
  }

  function polygon(points, color) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) {
      ctx.lineTo(points[i][0], points[i][1]);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
  }

  function text(value, x, y, size, color, align, weight, maxWidth) {
    ctx.save();
    ctx.textAlign = align || 'left';
    ctx.textBaseline = 'alphabetic';
    let fontSize = size;
    ctx.font = (weight || 600) + ' ' + fontSize + 'px Arial, Helvetica, sans-serif';
    if (maxWidth && ctx.measureText(value).width > maxWidth) {
      fontSize *= maxWidth / ctx.measureText(value).width;
      ctx.font = (weight || 600) + ' ' + fontSize + 'px Arial, Helvetica, sans-serif';
    }
    ctx.fillStyle = color;
    ctx.fillText(value, x, y);
    ctx.restore();
  }

  function bolt(x, y, size, color) {
    polygon([
      [x + size * 0.12, y - size * 0.55],
      [x - size * 0.39, y + size * 0.06],
      [x - size * 0.04, y + size * 0.06],
      [x - size * 0.15, y + size * 0.55],
      [x + size * 0.42, y - size * 0.13],
      [x + size * 0.08, y - size * 0.13]
    ], color);
  }

  // Rounded conduits are closed filled geometry. No stroked paths are used.
  function makeRoute(points, cornerRadius) {
    const samples = [points[0].slice()];
    let current = points[0].slice();

    function appendLine(end) {
      const start = current;
      const steps = Math.max(1, Math.ceil(Math.hypot(end[0] - start[0], end[1] - start[1]) / 10));
      for (let n = 1; n <= steps; n++) {
        const u = n / steps;
        samples.push([start[0] + (end[0] - start[0]) * u, start[1] + (end[1] - start[1]) * u]);
      }
      current = end.slice();
    }

    for (let i = 1; i < points.length - 1; i++) {
      const a = points[i - 1];
      const b = points[i];
      const c = points[i + 1];
      const before = Math.hypot(a[0] - b[0], a[1] - b[1]);
      const after = Math.hypot(c[0] - b[0], c[1] - b[1]);
      const cut = Math.min(cornerRadius, before * 0.42, after * 0.42);
      const entry = [b[0] + (a[0] - b[0]) * cut / before, b[1] + (a[1] - b[1]) * cut / before];
      const exit = [b[0] + (c[0] - b[0]) * cut / after, b[1] + (c[1] - b[1]) * cut / after];
      appendLine(entry);
      for (let n = 1; n <= 12; n++) {
        const u = n / 12;
        const v = 1 - u;
        samples.push([v * v * entry[0] + 2 * v * u * b[0] + u * u * exit[0], v * v * entry[1] + 2 * v * u * b[1] + u * u * exit[1]]);
      }
      current = exit.slice();
    }
    appendLine(points[points.length - 1]);

    const distance = [0];
    for (let i = 1; i < samples.length; i++) {
      distance.push(distance[i - 1] + Math.hypot(samples[i][0] - samples[i - 1][0], samples[i][1] - samples[i - 1][1]));
    }
    return { samples: samples, distance: distance, length: distance[distance.length - 1] };
  }

  function routePath(route, thickness) {
    const a = route.samples;
    const normals = [];
    for (let i = 0; i < a.length; i++) {
      const previous = a[Math.max(0, i - 1)];
      const next = a[Math.min(a.length - 1, i + 1)];
      const dx = next[0] - previous[0];
      const dy = next[1] - previous[1];
      const magnitude = Math.hypot(dx, dy) || 1;
      normals.push([-dy / magnitude * thickness * 0.5, dx / magnitude * thickness * 0.5]);
    }
    ctx.beginPath();
    ctx.moveTo(a[0][0] + normals[0][0], a[0][1] + normals[0][1]);
    for (let i = 1; i < a.length; i++) {
      ctx.lineTo(a[i][0] + normals[i][0], a[i][1] + normals[i][1]);
    }
    for (let i = a.length - 1; i >= 0; i--) {
      ctx.lineTo(a[i][0] - normals[i][0], a[i][1] - normals[i][1]);
    }
    ctx.closePath();
  }

  function routePose(route, distance) {
    const target = Math.max(0, Math.min(route.length, distance));
    let low = 1;
    let high = route.distance.length - 1;
    while (low < high) {
      const mid = (low + high) >> 1;
      if (route.distance[mid] < target) low = mid + 1;
      else high = mid;
    }
    const i = low;
    const previous = route.samples[i - 1];
    const next = route.samples[i];
    const span = route.distance[i] - route.distance[i - 1];
    const u = span > 0 ? (target - route.distance[i - 1]) / span : 0;
    return {
      x: previous[0] + (next[0] - previous[0]) * u,
      y: previous[1] + (next[1] - previous[1]) * u,
      angle: Math.atan2(next[1] - previous[1], next[0] - previous[0])
    };
  }

  function conduit(route, thickness, motion, spacing, packetColor) {
    routePath(route, thickness);
    ctx.fillStyle = P.navy;
    ctx.fill();
    ctx.save();
    routePath(route, thickness);
    ctx.clip();
    const count = Math.max(1, Math.round(route.length / spacing));
    const gap = route.length / count;
    const travel = ((motion % 1) + 1) % 1;
    for (let i = 0; i < count; i++) {
      const pose = routePose(route, (i + travel) * gap);
      ctx.save();
      ctx.translate(pose.x, pose.y);
      ctx.rotate(pose.angle);
      box(-10, -3.5, 20, 7, 3.5, packetColor || P.amber);
      ctx.restore();
    }
    ctx.restore();
  }

  function waveBand(x, y, w, amplitude, thickness, wavePhase, cycles, color, tapered) {
    const count = 64;
    ctx.beginPath();
    for (let i = 0; i <= count; i++) {
      const u = i / count;
      const taper = tapered ? Math.pow(Math.sin(Math.PI * u), 0.7) : 1;
      const py = y + Math.sin(u * TAU * cycles - wavePhase) * amplitude;
      const edge = py - thickness * 0.5 * taper;
      if (i === 0) ctx.moveTo(x + u * w, edge);
      else ctx.lineTo(x + u * w, edge);
    }
    for (let i = count; i >= 0; i--) {
      const u = i / count;
      const taper = tapered ? Math.pow(Math.sin(Math.PI * u), 0.7) : 1;
      const py = y + Math.sin(u * TAU * cycles - wavePhase) * amplitude;
      ctx.lineTo(x + u * w, py + thickness * 0.5 * taper);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
  }

  function processPipe(route, outerWidth, innerWidth, motion, spacing, fluid, marker) {
    routePath(route, outerWidth);
    ctx.fillStyle = P.navy;
    ctx.fill();
    routePath(route, innerWidth);
    ctx.fillStyle = fluid;
    ctx.fill();
    ctx.save();
    routePath(route, innerWidth);
    ctx.clip();
    const count = Math.max(1, Math.round(route.length / spacing));
    const gap = route.length / count;
    const offset = ((motion % 1) + 1) % 1;
    for (let i = 0; i < count; i++) {
      const pose = routePose(route, (i + offset) * gap);
      ctx.save();
      ctx.translate(pose.x, pose.y);
      ctx.rotate(pose.angle);
      box(-11, -3, 22, 6, 3, marker);
      ctx.restore();
    }
    ctx.restore();
  }

  function stageLabel(x, main, detail, maximum) {
    text(main, x, 914, 21, P.navy, 'center', 700, maximum);
    text(detail, x, 946, 15, P.navy, 'center', 500, maximum);
  }

  function energyBars(x, bottom, count, spacing, width, height, offset, color) {
    for (let i = 0; i < count; i++) {
      const h = 11 + height * (0.5 + 0.5 * Math.sin(phase * 2 - i * 0.35 + offset));
      box(x + i * spacing, bottom - h, width, h, 4, color);
    }
  }

  text('GEOTHERMAL ENERGY', 150, 156, 48, P.navy, 'left', 700, 900);
  text('HEAT EXTRACTION  /  POWER GENERATION  /  FLUID RETURN', 152, 192, 18, P.navy, 'left', 600, 1020);

  // A bounded geological section, made exclusively from opaque flat fills.
  box(150, 574, 1620, 274, 22, P.navy);
  ctx.save();
  roundedPath(158, 582, 1604, 258, 15);
  ctx.clip();
  ctx.fillStyle = P.terracotta;
