  // Production rises on the left; reinjection descends on the right.
  // Route endpoints are concealed by the reservoir terminal and plant casings.
  const production = makeRoute([[410, 801], [410, 535], [834, 535]], 34);
  const reinjection = makeRoute([[1082, 535], [1370, 535], [1370, 801]], 34);
  const workingSupply = makeRoute([[1082, 429], [1255, 429]], 20);
