  const P = {
    navy: '#182B49',
    blue: '#285CCD',
    cobalt: '#387CF2',
    pale: '#B7D1FB',
    ice: '#E5EDFA',
    white: '#FAF7EF',
    amber: '#FFBB59',
    coral: '#F17A64',
    gray: '#C9D2DF',
    terracotta: '#AD6458',
