  text('MICRO HYDRO', 150, 156, 48, P.navy, 'left', 700, 620);
  text('RUN-OF-RIVER  /  GENERATION  /  DISTRIBUTION', 152, 192, 18, P.navy, 'left', 600, 730);

  // Every route terminates beneath a casing, collar or water chamber.
  // The generous penstock bends remain wider than the filled pipe offset.
  const penstock = makeRoute([[535, 552], [640, 552], [640, 670], [816, 670]], 48);
  const tailrace = makeRoute([[984, 670], [1300, 670]], 16);
  const powerRoute = makeRoute([[995, 363], [1280, 363]], 18);
  fluidConduit(penstock, 58, 42, sceneProgress * 20, 94);
  fluidConduit(tailrace, 58, 42, sceneProgress * 20 + 0.25, 94);
  conduit(powerRoute, 15, sceneProgress * 15, 78, P.amber);

  // Mechanical shaft and stationary couplings are behind the two housings.
  box(889, 407, 22, 155, 6, P.navy);
  box(872, 452, 56, 25, 7, P.white);
  box(880, 460, 40, 9, 4, P.gray);

  // Elevated river intake. Only internal water elements are animated.
  box(150, 417, 420, 408, 22, P.white);
  box(150, 417, 420, 51, 22, P.navy);
  box(150, 446, 420, 22, 0, P.navy);
  text('RIVER INTAKE', 174, 452, 23, P.white, 'left', 700, 325);
  circle(541, 442, 6, P.amber);
  const intakeLevel = 0.88 + 0.004 * Math.sin(phase * 2);
  waterWell(172, 478, 376, 321, 12, intakeLevel, phase * 5);
  ctx.save();
  roundedPath(172, 478, 376, 321, 12);
  ctx.clip();
  waterPath(172, 478, 376, 321, intakeLevel, phase * 5, 1);
  ctx.clip();
  // Separate bubble lanes never enter the horizontal flow-marker corridor.
  for (let lane = 0; lane < 3; lane++) {
    const travel = (sceneProgress * 3 + lane / 3) % 1;
    const y = 813 - travel * 350;
    const x = 220 + lane * 59 + Math.sin(phase * 3 + lane) * 1.2;
    circle(x, y, 4.5, P.pale);
  }
  streamCapsules(389, 618, 86, sceneProgress * 15, 44);
  streamCapsules(389, 682, 86, sceneProgress * 15 + 0.35, 44);
  streamCapsules(389, 746, 86, sceneProgress * 15 + 0.7, 44);
  ctx.restore();
  // Fixed intake grille. Its openings and supports remain evenly spaced.
  for (let i = 0; i < 4; i++) box(493 + i * 11, 525, 5, 246, 2.5, P.navy);
  box(487, 535, 47, 9, 4, P.navy);
  box(487, 754, 47, 9, 4, P.navy);
  box(556, 522, 27, 60, 7, P.navy);
  box(563, 530, 13, 44, 4, P.blue);
  box(176, 825, 50, 14, 4, P.navy);
  box(494, 825, 50, 14, 4, P.navy);

  // Generator, bearing housing and instrument panel.
  box(785, 303, 230, 123, 20, P.white);
  box(785, 303, 230, 43, 20, P.navy);
  box(785, 326, 230, 20, 0, P.navy);
  text('GENERATOR', 807, 333, 20, P.white, 'left', 700, 176);
  box(806, 361, 98, 45, 8, P.navy);
  waveBand(815, 385, 80, 8, 4, phase * 6, 1.2, P.pale, false);
  for (let i = 0; i < 4; i++) box(925 + i * 18, 362, 8, 41, 4, P.gray);
  box(1004, 346, 23, 34, 6, P.navy);

  // Turbine chamber. The runner has a fixed silhouette and a single pivot.
  box(748, 505, 305, 320, 22, P.white);
  box(748, 505, 305, 50, 22, P.navy);
  box(748, 533, 305, 22, 0, P.navy);
  text('HYDRO TURBINE', 771, 540, 22, P.white, 'left', 700, 258);
  circle(900, 670, 111, P.navy);
  circle(900, 670, 100, P.cobalt);
  ctx.save();
  ctx.translate(900, 670);
  ctx.rotate(phase * 6);
  for (let blade = 0; blade < 8; blade++) {
    ctx.save();
    ctx.rotate(blade * TAU / 8);
    ctx.beginPath();
    ctx.moveTo(30, -8);
    ctx.bezierCurveTo(45, -22, 69, -14, 78, 5);
    ctx.lineTo(65, 16);
    ctx.bezierCurveTo(57, 1, 45, 8, 33, 13);
    ctx.closePath();
    ctx.fillStyle = P.white;
    ctx.fill();
    ctx.restore();
  }
  circle(0, 0, 37, P.navy);
  circle(0, 0, 17, P.amber);
  for (let i = 0; i < 3; i++) {
    const a = i * TAU / 3;
    circle(Math.cos(a) * 10, Math.sin(a) * 10, 2.4, P.navy);
  }
  ctx.restore();
  for (let i = 0; i < 4; i++) {
    const angle = Math.PI / 4 + i * Math.PI / 2;
    circle(900 + Math.cos(angle) * 129, 670 + Math.sin(angle) * 129, 4, P.navy);
  }
  box(734, 825, 333, 14, 6, P.navy);

  // A lower downstream channel makes the direction of water travel legible.
  box(1230, 578, 540, 247, 22, P.white);
  box(1230, 578, 540, 46, 22, P.navy);
  box(1230, 603, 540, 21, 0, P.navy);
  text('DOWNSTREAM', 1254, 610, 22, P.white, 'left', 700, 420);
  circle(1741, 601, 6, P.amber);
  const returnLevel = 0.94 + 0.004 * Math.sin(phase * 2 + 0.4);
  waterWell(1252, 636, 496, 164, 12, returnLevel, phase * 5 + 0.65);
  ctx.save();
  roundedPath(1252, 636, 496, 164, 12);
  ctx.clip();
  waterPath(1252, 636, 496, 164, returnLevel, phase * 5 + 0.65, 1);
  ctx.clip();
  streamCapsules(1273, 704, 452, sceneProgress * 20, 94);
  streamCapsules(1273, 759, 452, sceneProgress * 20 + 0.5, 94);
  ctx.restore();
  box(1217, 641, 27, 58, 7, P.navy);
  box(1224, 649, 13, 42, 4, P.blue);
  box(1257, 825, 50, 14, 4, P.navy);
  box(1693, 825, 50, 14, 4, P.navy);

  box(1265, 303, 290, 123, 20, P.navy);
  text('AC OUTPUT', 1287, 337, 21, P.white, 'left', 700, 225);
  bolt(1297, 380, 30, P.amber);
  for (let i = 0; i < 9; i++) {
    const h = 13 + 29 * (0.5 + 0.5 * Math.sin(phase * 2 - i * 0.4));
    box(1330 + i * 22, 405 - h, 13, h, 4, i > 6 ? P.amber : P.pale);
  }
  box(1253, 346, 24, 34, 6, P.navy);

  stageLabel(360, '01  RIVER INTAKE', 'CONTROLLED WATER FLOW', 420);
  stageLabel(900, '02  TURBINE + GENERATOR', 'WATER TO ELECTRICITY', 440);
  stageLabel(1500, '03  DOWNSTREAM FLOW', 'CONTINUOUS WATER RETURN', 500);
  ctx.restore();
}

/*
 * Concept 04: Renewable Hydrogen Electrolysis System
 * One scene | 25 seconds | seamless loop | pure Canvas 2D.
 * Render size: 3840 x 2160 (16:9); scales uniformly to FHD and 2K.
 * Suggested export frame rate: 60 fps.
 * Required encoder video bitrate: 100000000 bits per second or higher.
 * Bitrate must be configured in the host video encoder; draw() renders pixels only.
 * No external assets, DOM, imports, dependencies, glow, or stroked paths.
 */
function draw(ctx, time, width, height) {
  ctx.fillStyle = '#00FF00';
  ctx.fillRect(0, 0, width, height);

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowColor = 'transparent';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.filter = 'none';
  ctx.fillStyle = '#00FF00';
  ctx.fillRect(0, 0, width, height);

  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const scale = Math.min(width / 1920, height / 1080, minSide / 1080);
  const TAU = Math.PI * 2;
  const phase = TAU * (currentScene + sceneProgress);
  const P = {
    navy: '#182B49',
    blue: '#285CCD',
    cobalt: '#387CF2',
    pale: '#B7D1FB',
    ice: '#E5EDFA',
    white: '#FAF7EF',
    amber: '#FFBB59',
    coral: '#F17A64',
    gray: '#C9D2DF'
  };

  ctx.translate(width * 0.5, height * 0.5);
  ctx.scale(scale, scale);
  ctx.translate(-960, -540);

  function roundedPath(x, y, w, h, radius) {
    const r = Math.max(0, Math.min(radius, w * 0.5, h * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }

  function box(x, y, w, h, radius, color) {
    roundedPath(x, y, w, h, radius);
    ctx.fillStyle = color;
    ctx.fill();
  }

  function circle(x, y, radius, color) {
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, TAU);
    ctx.fillStyle = color;
    ctx.fill();
  }

  function polygon(points, color) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) {
      ctx.lineTo(points[i][0], points[i][1]);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
  }

  function text(value, x, y, size, color, align, weight, maxWidth) {
    ctx.save();
    ctx.textAlign = align || 'left';
    ctx.textBaseline = 'alphabetic';
    let fontSize = size;
    ctx.font = (weight || 600) + ' ' + fontSize + 'px Arial, Helvetica, sans-serif';
    if (maxWidth && ctx.measureText(value).width > maxWidth) {
      fontSize *= maxWidth / ctx.measureText(value).width;
      ctx.font = (weight || 600) + ' ' + fontSize + 'px Arial, Helvetica, sans-serif';
    }
    ctx.fillStyle = color;
    ctx.fillText(value, x, y);
    ctx.restore();
  }

  function bolt(x, y, size, color) {
    polygon([
      [x + size * 0.12, y - size * 0.55],
      [x - size * 0.39, y + size * 0.06],
      [x - size * 0.04, y + size * 0.06],
      [x - size * 0.15, y + size * 0.55],
      [x + size * 0.42, y - size * 0.13],
      [x + size * 0.08, y - size * 0.13]
    ], color);
  }

  // Rounded conduits are closed filled geometry. No stroked paths are used.
  function makeRoute(points, cornerRadius) {
    const samples = [points[0].slice()];
    let current = points[0].slice();

    function appendLine(end) {
      const start = current;
      const steps = Math.max(1, Math.ceil(Math.hypot(end[0] - start[0], end[1] - start[1]) / 10));
      for (let n = 1; n <= steps; n++) {
        const u = n / steps;
        samples.push([start[0] + (end[0] - start[0]) * u, start[1] + (end[1] - start[1]) * u]);
      }
      current = end.slice();
    }

    for (let i = 1; i < points.length - 1; i++) {
      const a = points[i - 1];
      const b = points[i];
      const c = points[i + 1];
      const before = Math.hypot(a[0] - b[0], a[1] - b[1]);
      const after = Math.hypot(c[0] - b[0], c[1] - b[1]);
      const cut = Math.min(cornerRadius, before * 0.42, after * 0.42);
      const entry = [b[0] + (a[0] - b[0]) * cut / before, b[1] + (a[1] - b[1]) * cut / before];
      const exit = [b[0] + (c[0] - b[0]) * cut / after, b[1] + (c[1] - b[1]) * cut / after];
      appendLine(entry);
      for (let n = 1; n <= 12; n++) {
        const u = n / 12;
        const v = 1 - u;
        samples.push([v * v * entry[0] + 2 * v * u * b[0] + u * u * exit[0], v * v * entry[1] + 2 * v * u * b[1] + u * u * exit[1]]);
      }
      current = exit.slice();
    }
    appendLine(points[points.length - 1]);

    const distance = [0];
    for (let i = 1; i < samples.length; i++) {
      distance.push(distance[i - 1] + Math.hypot(samples[i][0] - samples[i - 1][0], samples[i][1] - samples[i - 1][1]));
    }
    return { samples: samples, distance: distance, length: distance[distance.length - 1] };
  }

  function routePath(route, thickness) {
    const a = route.samples;
    const normals = [];
    for (let i = 0; i < a.length; i++) {
      const previous = a[Math.max(0, i - 1)];
      const next = a[Math.min(a.length - 1, i + 1)];
      const dx = next[0] - previous[0];
      const dy = next[1] - previous[1];
      const magnitude = Math.hypot(dx, dy) || 1;
      normals.push([-dy / magnitude * thickness * 0.5, dx / magnitude * thickness * 0.5]);
    }
    ctx.beginPath();
    ctx.moveTo(a[0][0] + normals[0][0], a[0][1] + normals[0][1]);
    for (let i = 1; i < a.length; i++) {
      ctx.lineTo(a[i][0] + normals[i][0], a[i][1] + normals[i][1]);
    }
    for (let i = a.length - 1; i >= 0; i--) {
      ctx.lineTo(a[i][0] - normals[i][0], a[i][1] - normals[i][1]);
    }
    ctx.closePath();
  }

  function routePose(route, distance) {
    const target = Math.max(0, Math.min(route.length, distance));
    let low = 1;
    let high = route.distance.length - 1;
    while (low < high) {
      const mid = (low + high) >> 1;
      if (route.distance[mid] < target) low = mid + 1;
      else high = mid;
    }
    const i = low;
    const previous = route.samples[i - 1];
    const next = route.samples[i];
    const span = route.distance[i] - route.distance[i - 1];
    const u = span > 0 ? (target - route.distance[i - 1]) / span : 0;
    return {
      x: previous[0] + (next[0] - previous[0]) * u,
      y: previous[1] + (next[1] - previous[1]) * u,
      angle: Math.atan2(next[1] - previous[1], next[0] - previous[0])
    };
  }

  function conduit(route, thickness, motion, spacing, packetColor) {
    routePath(route, thickness);
    ctx.fillStyle = P.navy;
    ctx.fill();
    ctx.save();
    routePath(route, thickness);
    ctx.clip();
    const count = Math.max(1, Math.round(route.length / spacing));
    const gap = route.length / count;
    const travel = ((motion % 1) + 1) % 1;
    for (let i = 0; i < count; i++) {
      const pose = routePose(route, (i + travel) * gap);
      ctx.save();
      ctx.translate(pose.x, pose.y);
      ctx.rotate(pose.angle);
      box(-10, -3.5, 20, 7, 3.5, packetColor || P.amber);
      ctx.restore();
    }
    ctx.restore();
  }

  function waveBand(x, y, w, amplitude, thickness, wavePhase, cycles, color, tapered) {
    const count = 64;
    ctx.beginPath();
    for (let i = 0; i <= count; i++) {
      const u = i / count;
      const taper = tapered ? Math.pow(Math.sin(Math.PI * u), 0.7) : 1;
      const py = y + Math.sin(u * TAU * cycles - wavePhase) * amplitude;
      const edge = py - thickness * 0.5 * taper;
      if (i === 0) ctx.moveTo(x + u * w, edge);
      else ctx.lineTo(x + u * w, edge);
    }
    for (let i = count; i >= 0; i--) {
      const u = i / count;
      const taper = tapered ? Math.pow(Math.sin(Math.PI * u), 0.7) : 1;
      const py = y + Math.sin(u * TAU * cycles - wavePhase) * amplitude;
      ctx.lineTo(x + u * w, py + thickness * 0.5 * taper);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
  }

  function waterPath(x, y, w, h, level, waterPhase, layer) {
    const base = y + h * (1 - level);
    ctx.beginPath();
    ctx.moveTo(x, y + h + 8);
    for (let i = 0; i <= 56; i++) {
      const u = i / 56;
      const wave = Math.sin(u * TAU * 1.12 - waterPhase + layer * 1.1) * (layer === 0 ? 4 : 3);
      ctx.lineTo(x + u * w, base + (layer === 0 ? -5 : 3) + wave);
    }
    ctx.lineTo(x + w, y + h + 8);
    ctx.closePath();
  }

  function waterWell(x, y, w, h, radius, level, waterPhase) {
    box(x, y, w, h, radius, P.ice);
    ctx.save();
    roundedPath(x, y, w, h, radius);
    ctx.clip();
    for (let layer = 0; layer < 2; layer++) {
      waterPath(x, y, w, h, level, waterPhase, layer);
      ctx.fillStyle = layer === 0 ? P.pale : P.cobalt;
      ctx.fill();
    }
    ctx.restore();
  }

  function fluidConduit(route, outside, inside, motion, spacing) {
    routePath(route, outside);
    ctx.fillStyle = P.navy;
    ctx.fill();
    routePath(route, inside);
    ctx.fillStyle = P.cobalt;
    ctx.fill();
    ctx.save();
    routePath(route, inside);
    ctx.clip();
    const count = Math.max(1, Math.round(route.length / spacing));
    const gap = route.length / count;
    const travel = ((motion % 1) + 1) % 1;
    for (let i = 0; i < count; i++) {
