  ctx.restore();
}

/*
 * Concept 01: Solar Power Distribution Hub
 * One scene | 25 seconds | seamless loop | pure Canvas 2D.
 * Render size: 3840 x 2160 (16:9); scales uniformly to FHD and 2K.
 * Suggested export frame rate: 60 fps.
 * Required encoder video bitrate: 100000000 bits per second or higher.
 * Bitrate must be configured in the host video encoder; draw() renders pixels only.
 * No external assets, DOM, imports, dependencies, glow, or stroked paths.
 */
function draw(ctx, time, width, height) {
  ctx.fillStyle = '#00FF00';
  ctx.fillRect(0, 0, width, height);

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowColor = 'transparent';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.filter = 'none';
  ctx.fillStyle = '#00FF00';
  ctx.fillRect(0, 0, width, height);

  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const scale = Math.min(width / 1920, height / 1080, minSide / 1080);
  const TAU = Math.PI * 2;
  const phase = TAU * (currentScene + sceneProgress);
  const P = {
    navy: '#182B49',
    blue: '#285CCD',
    cobalt: '#387CF2',
    pale: '#B7D1FB',
    ice: '#E5EDFA',
    white: '#FAF7EF',
    amber: '#FFBB59',
    coral: '#F17A64',
    gray: '#C9D2DF'
  };

  ctx.translate(width * 0.5, height * 0.5);
  ctx.scale(scale, scale);
  ctx.translate(-960, -540);

  function roundedPath(x, y, w, h, radius) {
    const r = Math.max(0, Math.min(radius, w * 0.5, h * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }

  function box(x, y, w, h, radius, color) {
    roundedPath(x, y, w, h, radius);
    ctx.fillStyle = color;
    ctx.fill();
  }

  function circle(x, y, radius, color) {
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, TAU);
    ctx.fillStyle = color;
    ctx.fill();
  }

  function polygon(points, color) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) {
      ctx.lineTo(points[i][0], points[i][1]);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
  }

  function text(value, x, y, size, color, align, weight, maxWidth) {
    ctx.save();
    ctx.textAlign = align || 'left';
    ctx.textBaseline = 'alphabetic';
    let fontSize = size;
    ctx.font = (weight || 600) + ' ' + fontSize + 'px Arial, Helvetica, sans-serif';
    if (maxWidth && ctx.measureText(value).width > maxWidth) {
      fontSize *= maxWidth / ctx.measureText(value).width;
      ctx.font = (weight || 600) + ' ' + fontSize + 'px Arial, Helvetica, sans-serif';
    }
    ctx.fillStyle = color;
    ctx.fillText(value, x, y);
    ctx.restore();
  }

  function bolt(x, y, size, color) {
    polygon([
      [x + size * 0.12, y - size * 0.55],
      [x - size * 0.39, y + size * 0.06],
      [x - size * 0.04, y + size * 0.06],
      [x - size * 0.15, y + size * 0.55],
      [x + size * 0.42, y - size * 0.13],
      [x + size * 0.08, y - size * 0.13]
    ], color);
  }

  // Rounded conduits are closed filled geometry. No stroked paths are used.
  function makeRoute(points, cornerRadius) {
    const samples = [points[0].slice()];
    let current = points[0].slice();

    function appendLine(end) {
      const start = current;
      const steps = Math.max(1, Math.ceil(Math.hypot(end[0] - start[0], end[1] - start[1]) / 10));
      for (let n = 1; n <= steps; n++) {
        const u = n / steps;
        samples.push([start[0] + (end[0] - start[0]) * u, start[1] + (end[1] - start[1]) * u]);
      }
      current = end.slice();
    }

    for (let i = 1; i < points.length - 1; i++) {
      const a = points[i - 1];
      const b = points[i];
      const c = points[i + 1];
      const before = Math.hypot(a[0] - b[0], a[1] - b[1]);
      const after = Math.hypot(c[0] - b[0], c[1] - b[1]);
      const cut = Math.min(cornerRadius, before * 0.42, after * 0.42);
      const entry = [b[0] + (a[0] - b[0]) * cut / before, b[1] + (a[1] - b[1]) * cut / before];
      const exit = [b[0] + (c[0] - b[0]) * cut / after, b[1] + (c[1] - b[1]) * cut / after];
      appendLine(entry);
      for (let n = 1; n <= 12; n++) {
        const u = n / 12;
        const v = 1 - u;
        samples.push([v * v * entry[0] + 2 * v * u * b[0] + u * u * exit[0], v * v * entry[1] + 2 * v * u * b[1] + u * u * exit[1]]);
      }
      current = exit.slice();
    }
    appendLine(points[points.length - 1]);

    const distance = [0];
    for (let i = 1; i < samples.length; i++) {
      distance.push(distance[i - 1] + Math.hypot(samples[i][0] - samples[i - 1][0], samples[i][1] - samples[i - 1][1]));
    }
    return { samples: samples, distance: distance, length: distance[distance.length - 1] };
  }

  function routePath(route, thickness) {
    const a = route.samples;
    const normals = [];
    for (let i = 0; i < a.length; i++) {
      const previous = a[Math.max(0, i - 1)];
      const next = a[Math.min(a.length - 1, i + 1)];
      const dx = next[0] - previous[0];
      const dy = next[1] - previous[1];
      const magnitude = Math.hypot(dx, dy) || 1;
      normals.push([-dy / magnitude * thickness * 0.5, dx / magnitude * thickness * 0.5]);
    }
    ctx.beginPath();
    ctx.moveTo(a[0][0] + normals[0][0], a[0][1] + normals[0][1]);
    for (let i = 1; i < a.length; i++) {
      ctx.lineTo(a[i][0] + normals[i][0], a[i][1] + normals[i][1]);
    }
    for (let i = a.length - 1; i >= 0; i--) {
      ctx.lineTo(a[i][0] - normals[i][0], a[i][1] - normals[i][1]);
    }
    ctx.closePath();
  }

  function routePose(route, distance) {
    const target = Math.max(0, Math.min(route.length, distance));
    let low = 1;
    let high = route.distance.length - 1;
    while (low < high) {
      const mid = (low + high) >> 1;
      if (route.distance[mid] < target) low = mid + 1;
      else high = mid;
    }
    const i = low;
    const previous = route.samples[i - 1];
    const next = route.samples[i];
    const span = route.distance[i] - route.distance[i - 1];
    const u = span > 0 ? (target - route.distance[i - 1]) / span : 0;
    return {
      x: previous[0] + (next[0] - previous[0]) * u,
      y: previous[1] + (next[1] - previous[1]) * u,
      angle: Math.atan2(next[1] - previous[1], next[0] - previous[0])
    };
  }

  function conduit(route, thickness, motion, spacing, packetColor) {
    routePath(route, thickness);
    ctx.fillStyle = P.navy;
    ctx.fill();
    ctx.save();
    routePath(route, thickness);
    ctx.clip();
    const count = Math.max(1, Math.round(route.length / spacing));
    const gap = route.length / count;
    const travel = ((motion % 1) + 1) % 1;
    for (let i = 0; i < count; i++) {
      const pose = routePose(route, (i + travel) * gap);
      ctx.save();
      ctx.translate(pose.x, pose.y);
      ctx.rotate(pose.angle);
      box(-10, -3.5, 20, 7, 3.5, packetColor || P.amber);
      ctx.restore();
    }
    ctx.restore();
  }

  function waveBand(x, y, w, amplitude, thickness, wavePhase, cycles, color, tapered) {
    const count = 64;
    ctx.beginPath();
    for (let i = 0; i <= count; i++) {
      const u = i / count;
      const taper = tapered ? Math.pow(Math.sin(Math.PI * u), 0.7) : 1;
      const py = y + Math.sin(u * TAU * cycles - wavePhase) * amplitude;
      const edge = py - thickness * 0.5 * taper;
      if (i === 0) ctx.moveTo(x + u * w, edge);
      else ctx.lineTo(x + u * w, edge);
    }
    for (let i = count; i >= 0; i--) {
      const u = i / count;
      const taper = tapered ? Math.pow(Math.sin(Math.PI * u), 0.7) : 1;
      const py = y + Math.sin(u * TAU * cycles - wavePhase) * amplitude;
      ctx.lineTo(x + u * w, py + thickness * 0.5 * taper);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
  }

  // All four stages remain present for the entire single-scene loop.
  text('SOLAR POWER', 150, 156, 48, P.navy, 'left', 700, 600);
  text('GENERATION  /  CONVERSION  /  STORAGE', 152, 192, 18, P.navy, 'left', 600, 640);

  const solarInput = makeRoute([[300, 540], [868, 540]], 18);
  const batteryFeed = makeRoute([[1080, 540], [1254, 540]], 18);
  const homeFeed = makeRoute([[1438, 540], [1508, 540], [1508, 622], [1614, 622]], 22);
  conduit(solarInput, 15, sceneProgress * 10, 74, P.amber);
  conduit(batteryFeed, 15, sceneProgress * 10 + 0.2, 74, P.amber);
  conduit(homeFeed, 15, sceneProgress * 10 + 0.4, 74, P.amber);

  // The sun rotates as rigid filled shapes, without bloom or light effects.
  const sunX = 430;
  const sunY = 295;
  ctx.save();
  ctx.translate(sunX, sunY);
  ctx.rotate(phase);
  for (let i = 0; i < 12; i++) {
    ctx.save();
    ctx.rotate(i * TAU / 12);
    box(-4, -91, 8, 18, 4, P.amber);
    ctx.restore();
  }
  ctx.restore();
  circle(sunX, sunY, 57, P.amber);

  // Three front-facing modules; the internal details stay clipped to cells.
  for (let panel = 0; panel < 3; panel++) {
    const x = 150 + panel * 185;
    const y = 411;
    box(x, y, 168, 240, 12, P.white);
    box(x + 10, y + 10, 148, 220, 7, P.navy);
    for (let row = 0; row < 4; row++) {
      for (let col = 0; col < 3; col++) {
        const cx = x + 16 + col * 47;
        const cy = y + 17 + row * 53;
        box(cx, cy, 42, 47, 4, P.blue);
        box(cx + 7, cy + 8, 27, 4, 2, P.pale);
        box(cx + 7, cy + 19, 14, 4, 2, P.cobalt);
        ctx.save();
        roundedPath(cx + 6, cy + 34, 30, 5, 2.5);
        ctx.clip();
        const position = ((sceneProgress * 5 + row / 4 + col / 3 + panel / 3) % 1) * 48 - 12;
        box(cx + 6 + position, cy + 34, 12, 5, 2.5, P.white);
        ctx.restore();
      }
    }
    box(x + 55, 651, 18, 54, 4, P.navy);
    box(x + 95, 651, 18, 54, 4, P.navy);
    box(x + 34, 699, 100, 13, 6, P.navy);
  }
  box(705, 517, 32, 46, 8, P.navy);
  box(711, 526, 20, 28, 4, P.amber);

  // Inverter housing and fixed display: no changing labels or layout shifts.
  box(839, 517, 24, 46, 7, P.navy);
  box(1087, 517, 24, 46, 7, P.navy);
  box(851, 366, 248, 346, 22, P.white);
  box(851, 366, 248, 60, 22, P.navy);
  box(851, 402, 248, 24, 0, P.navy);
  text('INVERTER', 875, 404, 23, P.white, 'left', 700, 168);
  circle(1070, 396, 6, P.amber);
  box(875, 451, 200, 115, 14, P.navy);
  text('DC', 891, 480, 15, P.pale, 'left', 600, 46);
  text('AC', 1057, 480, 15, P.pale, 'right', 600, 46);
  for (let i = 0; i < 8; i++) {
    const h = 19 + 25 * (0.5 + 0.5 * Math.sin(phase * 2 - i * 0.48));
    box(892 + i * 21, 546 - h, 12, h, 4, i > 5 ? P.amber : P.cobalt);
  }
  circle(975, 602, 18, P.ice);
  bolt(975, 602, 24, P.blue);
  for (let i = 0; i < 7; i++) box(879 + i * 28, 648, 16, 7, 3.5, P.gray);
  for (let i = 0; i < 7; i++) box(879 + i * 28, 664, 16, 7, 3.5, P.gray);
  circle(873, 690, 3.5, P.navy);
  circle(1077, 690, 3.5, P.navy);

  // Storage uses opaque clipped wave fills inspired by the reference video.
  box(1217, 517, 27, 46, 7, P.navy);
  box(1441, 517, 27, 46, 7, P.navy);
  box(1291, 386, 100, 22, 7, P.navy);
  box(1230, 407, 222, 305, 22, P.white);
  box(1250, 430, 182, 231, 12, P.navy);
  ctx.save();
  roundedPath(1258, 438, 166, 215, 7);
  ctx.clip();
  ctx.fillStyle = P.ice;
  ctx.fillRect(1258, 438, 166, 215);
  const level = 0.57 + 0.105 * Math.sin(phase * 2 - 0.6);
  const surface = 653 - 215 * level;
  for (let layer = 0; layer < 2; layer++) {
    ctx.beginPath();
    ctx.moveTo(1258, 660);
    for (let i = 0; i <= 48; i++) {
      const u = i / 48;
      const wave = Math.sin(u * TAU + phase * 5 + layer * 1.3) * (layer === 0 ? 4 : 3);
      ctx.lineTo(1258 + u * 166, surface + (layer === 0 ? -6 : 4) + wave);
    }
    ctx.lineTo(1424, 660);
    ctx.closePath();
    ctx.fillStyle = layer === 0 ? P.pale : P.cobalt;
    ctx.fill();
  }
  for (let i = 0; i < 5; i++) box(1270, 462 + i * 36, 11, 4, 2, P.navy);
  bolt(1344, 551, 52, P.navy);
  ctx.restore();
  for (let i = 0; i < 5; i++) box(1262 + i * 35, 679, 22, 7, 3.5, i < 3 ? P.cobalt : P.gray);

  // Consumer building. Roof, walls, windows and socket are intentional joins.
  box(1583, 599, 27, 46, 7, P.navy);
  polygon([[1600, 503], [1690, 421], [1780, 503]], P.white);
  polygon([[1573, 501], [1690, 399], [1807, 501], [1784, 521], [1690, 439], [1596, 521]], P.navy);
  box(1600, 497, 180, 215, 8, P.white);
  box(1620, 532, 53, 54, 7, P.blue);
  box(1705, 532, 53, 54, 7, P.blue);
  box(1644, 532, 5, 54, 0, P.white);
  box(1620, 556, 53, 5, 0, P.white);
  box(1729, 532, 5, 54, 0, P.white);
  box(1705, 556, 53, 5, 0, P.white);
  box(1664, 624, 54, 88, 7, P.navy);
  circle(1705, 668, 3.5, P.amber);
  box(1620, 624, 27, 27, 5, P.ice);
  bolt(1634, 638, 18, P.blue);
  box(1588, 707, 204, 13, 6, P.navy);

  // Reserved label rows maintain the same spacing at every resolution.
  const labels = [
    [420, '01  GENERATION', 'PHOTOVOLTAIC ARRAY', 520],
    [975, '02  CONVERSION', 'DC TO AC', 260],
    [1341, '03  STORAGE', 'BATTERY SYSTEM', 246],
    [1690, '04  CONSUMPTION', 'LOCAL ENERGY USE', 280]
  ];
  for (let i = 0; i < labels.length; i++) {
    const a = labels[i];
    text(a[1], a[0], 783, 22, P.navy, 'center', 700, a[3]);
    text(a[2], a[0], 815, 15, P.navy, 'center', 500, a[3]);
  }
  ctx.restore();
}

/*
 * Concept 02: Wind Farm Energy Network
 * One scene | 25 seconds | seamless loop | pure Canvas 2D.
 * Render size: 3840 x 2160 (16:9); scales uniformly to FHD and 2K.
 * Suggested export frame rate: 60 fps.
 * Required encoder video bitrate: 100000000 bits per second or higher.
 * Bitrate must be configured in the host video encoder; draw() renders pixels only.
 * No external assets, DOM, imports, dependencies, glow, or stroked paths.
 */
function draw(ctx, time, width, height) {
  ctx.fillStyle = '#00FF00';
  ctx.fillRect(0, 0, width, height);

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowColor = 'transparent';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.filter = 'none';
  ctx.fillStyle = '#00FF00';
  ctx.fillRect(0, 0, width, height);

  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  const scale = Math.min(width / 1920, height / 1080, minSide / 1080);
  const TAU = Math.PI * 2;
  const phase = TAU * (currentScene + sceneProgress);
  const P = {
    navy: '#182B49',
    blue: '#285CCD',
    cobalt: '#387CF2',
    pale: '#B7D1FB',
    ice: '#E5EDFA',
    white: '#FAF7EF',
    amber: '#FFBB59',
    coral: '#F17A64',
    gray: '#C9D2DF'
  };

  ctx.translate(width * 0.5, height * 0.5);
  ctx.scale(scale, scale);
  ctx.translate(-960, -540);

  function roundedPath(x, y, w, h, radius) {
    const r = Math.max(0, Math.min(radius, w * 0.5, h * 0.5));
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }

  function box(x, y, w, h, radius, color) {
    roundedPath(x, y, w, h, radius);
    ctx.fillStyle = color;
    ctx.fill();
  }

  function circle(x, y, radius, color) {
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, TAU);
    ctx.fillStyle = color;
    ctx.fill();
  }

  function polygon(points, color) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) {
      ctx.lineTo(points[i][0], points[i][1]);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
  }

  function text(value, x, y, size, color, align, weight, maxWidth) {
    ctx.save();
    ctx.textAlign = align || 'left';
    ctx.textBaseline = 'alphabetic';
    let fontSize = size;
    ctx.font = (weight || 600) + ' ' + fontSize + 'px Arial, Helvetica, sans-serif';
    if (maxWidth && ctx.measureText(value).width > maxWidth) {
      fontSize *= maxWidth / ctx.measureText(value).width;
      ctx.font = (weight || 600) + ' ' + fontSize + 'px Arial, Helvetica, sans-serif';
    }
    ctx.fillStyle = color;
    ctx.fillText(value, x, y);
    ctx.restore();
  }

  function bolt(x, y, size, color) {
    polygon([
      [x + size * 0.12, y - size * 0.55],
      [x - size * 0.39, y + size * 0.06],
      [x - size * 0.04, y + size * 0.06],
      [x - size * 0.15, y + size * 0.55],
      [x + size * 0.42, y - size * 0.13],
      [x + size * 0.08, y - size * 0.13]
    ], color);
  }

  // Rounded conduits are closed filled geometry. No stroked paths are used.
  function makeRoute(points, cornerRadius) {
    const samples = [points[0].slice()];
    let current = points[0].slice();

    function appendLine(end) {
      const start = current;
      const steps = Math.max(1, Math.ceil(Math.hypot(end[0] - start[0], end[1] - start[1]) / 10));
      for (let n = 1; n <= steps; n++) {
        const u = n / steps;
        samples.push([start[0] + (end[0] - start[0]) * u, start[1] + (end[1] - start[1]) * u]);
      }
      current = end.slice();
    }

    for (let i = 1; i < points.length - 1; i++) {
      const a = points[i - 1];
      const b = points[i];
      const c = points[i + 1];
      const before = Math.hypot(a[0] - b[0], a[1] - b[1]);
      const after = Math.hypot(c[0] - b[0], c[1] - b[1]);
      const cut = Math.min(cornerRadius, before * 0.42, after * 0.42);
      const entry = [b[0] + (a[0] - b[0]) * cut / before, b[1] + (a[1] - b[1]) * cut / before];
      const exit = [b[0] + (c[0] - b[0]) * cut / after, b[1] + (c[1] - b[1]) * cut / after];
      appendLine(entry);
      for (let n = 1; n <= 12; n++) {
        const u = n / 12;
        const v = 1 - u;
        samples.push([v * v * entry[0] + 2 * v * u * b[0] + u * u * exit[0], v * v * entry[1] + 2 * v * u * b[1] + u * u * exit[1]]);
      }
      current = exit.slice();
    }
    appendLine(points[points.length - 1]);

    const distance = [0];
    for (let i = 1; i < samples.length; i++) {
      distance.push(distance[i - 1] + Math.hypot(samples[i][0] - samples[i - 1][0], samples[i][1] - samples[i - 1][1]));
    }
    return { samples: samples, distance: distance, length: distance[distance.length - 1] };
  }

  function routePath(route, thickness) {
    const a = route.samples;
    const normals = [];
    for (let i = 0; i < a.length; i++) {
      const previous = a[Math.max(0, i - 1)];
      const next = a[Math.min(a.length - 1, i + 1)];
      const dx = next[0] - previous[0];
      const dy = next[1] - previous[1];
      const magnitude = Math.hypot(dx, dy) || 1;
      normals.push([-dy / magnitude * thickness * 0.5, dx / magnitude * thickness * 0.5]);
    }
    ctx.beginPath();
    ctx.moveTo(a[0][0] + normals[0][0], a[0][1] + normals[0][1]);
    for (let i = 1; i < a.length; i++) {
      ctx.lineTo(a[i][0] + normals[i][0], a[i][1] + normals[i][1]);
    }
    for (let i = a.length - 1; i >= 0; i--) {
      ctx.lineTo(a[i][0] - normals[i][0], a[i][1] - normals[i][1]);
    }
    ctx.closePath();
  }

  function routePose(route, distance) {
    const target = Math.max(0, Math.min(route.length, distance));
    let low = 1;
    let high = route.distance.length - 1;
    while (low < high) {
      const mid = (low + high) >> 1;
      if (route.distance[mid] < target) low = mid + 1;
      else high = mid;
    }
    const i = low;
    const previous = route.samples[i - 1];
    const next = route.samples[i];
    const span = route.distance[i] - route.distance[i - 1];
    const u = span > 0 ? (target - route.distance[i - 1]) / span : 0;
    return {
      x: previous[0] + (next[0] - previous[0]) * u,
      y: previous[1] + (next[1] - previous[1]) * u,
      angle: Math.atan2(next[1] - previous[1], next[0] - previous[0])
    };
  }

  function conduit(route, thickness, motion, spacing, packetColor) {
    routePath(route, thickness);
    ctx.fillStyle = P.navy;
    ctx.fill();
    ctx.save();
    routePath(route, thickness);
    ctx.clip();
    const count = Math.max(1, Math.round(route.length / spacing));
    const gap = route.length / count;
    const travel = ((motion % 1) + 1) % 1;
    for (let i = 0; i < count; i++) {
      const pose = routePose(route, (i + travel) * gap);
      ctx.save();
      ctx.translate(pose.x, pose.y);
      ctx.rotate(pose.angle);
      box(-10, -3.5, 20, 7, 3.5, packetColor || P.amber);
      ctx.restore();
    }
    ctx.restore();
  }

  function waveBand(x, y, w, amplitude, thickness, wavePhase, cycles, color, tapered) {
    const count = 64;
    ctx.beginPath();
    for (let i = 0; i <= count; i++) {
      const u = i / count;
      const taper = tapered ? Math.pow(Math.sin(Math.PI * u), 0.7) : 1;
      const py = y + Math.sin(u * TAU * cycles - wavePhase) * amplitude;
      const edge = py - thickness * 0.5 * taper;
      if (i === 0) ctx.moveTo(x + u * w, edge);
      else ctx.lineTo(x + u * w, edge);
    }
    for (let i = count; i >= 0; i--) {
      const u = i / count;
      const taper = tapered ? Math.pow(Math.sin(Math.PI * u), 0.7) : 1;
      const py = y + Math.sin(u * TAU * cycles - wavePhase) * amplitude;
      ctx.lineTo(x + u * w, py + thickness * 0.5 * taper);
    }
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
  }

  text('WIND ENERGY', 150, 156, 48, P.navy, 'left', 700, 600);
  text('TURBINES  /  CONVERSION  /  DISTRIBUTION', 152, 192, 18, P.navy, 'left', 600, 650);

  // The air ribbons occupy their own corridor, clear of every rotor sweep.
  waveBand(1260, 276, 484, 9, 8, phase * 5, 1.25, P.white, true);
  waveBand(1310, 324, 432, 8, 7, phase * 5 + 0.9, 1.05, P.pale, true);
  waveBand(1260, 372, 484, 9, 8, phase * 5 + 1.8, 1.25, P.white, true);

  // A shared bus deliberately joins the three drop lines at fixed junctions.
  const bus = makeRoute([[320, 850], [1320, 850], [1320, 696], [1428, 696]], 26);
  conduit(bus, 15, sceneProgress * 20, 102, P.amber);
  const turbines = [
    { x: 320, y: 449, radius: 130, turns: 8, offset: 0.18, id: '01' },
    { x: 700, y: 369, radius: 164, turns: 7, offset: 0.94, id: '02' },
    { x: 1080, y: 462, radius: 126, turns: 9, offset: 1.7, id: '03' }
  ];

  for (let i = 0; i < turbines.length; i++) {
    const a = turbines[i];
    const drop = makeRoute([[a.x, 780], [a.x, 850]], 12);
    conduit(drop, 15, sceneProgress * 10 + i / 3, 68, P.amber);
    circle(a.x, 850, 10, P.navy);
    circle(a.x, 850, 4, P.amber);
  }

  function turbine(a, index) {
    // Stationary tapered tower and foundation; all geometry is front elevation.
    polygon([
      [a.x - 10, a.y + 12], [a.x + 10, a.y + 12],
      [a.x + 23, 780], [a.x - 23, 780]
    ], P.navy);
    box(a.x - 21, 721, 42, 27, 3, P.blue);
    for (let i = 0; i < 3; i++) box(a.x - 10 + i * 8, 730, 4, 9, 2, P.pale);
    box(a.x - 42, 775, 84, 14, 6, P.white);
    box(a.x - 58, 788, 116, 14, 7, P.navy);
    box(a.x - 31, a.y - 16, 62, 32, 15, P.blue);

    // Rigid rotor: one transform around the hub, constant angular velocity.
    ctx.save();
    ctx.translate(a.x, a.y);
    ctx.rotate(phase * a.turns + a.offset);
    const r = a.radius;
    for (let blade = 0; blade < 3; blade++) {
      ctx.save();
      ctx.rotate(blade * TAU / 3);
      ctx.beginPath();
      ctx.moveTo(-9, -12);
      ctx.bezierCurveTo(-16, -28, -18, -47, -14, -66);
      ctx.lineTo(-5, -r + 14);
      ctx.quadraticCurveTo(-3, -r, 4, -r);
      ctx.quadraticCurveTo(10, -r + 1, 10, -r + 13);
      ctx.lineTo(17, -51);
      ctx.quadraticCurveTo(22, -25, 9, -10);
      ctx.closePath();
      ctx.fillStyle = P.white;
      ctx.fill();

      // Inlaid tip marker is clipped to the blade silhouette.
      ctx.save();
      ctx.clip();
      box(-18, -r + 17, 42, 8, 0, index === 1 ? P.coral : P.cobalt);
      ctx.restore();
      ctx.restore();
    }
    circle(0, 0, 27, P.navy);
    circle(0, 0, 16, P.pale);
    circle(0, 0, 6, P.amber);
    ctx.restore();

    text('TURBINE ' + a.id, a.x, 915, 21, P.navy, 'center', 700, 230);
    text('WIND INPUT', a.x, 946, 15, P.navy, 'center', 500, 230);
  }

  for (let i = 0; i < turbines.length; i++) turbine(turbines[i], i);

  // Output meter is kept above the substation with a dedicated clear gap.
  box(1420, 451, 300, 66, 14, P.navy);
  text('OUTPUT', 1441, 490, 18, P.white, 'left', 700, 88);
  for (let i = 0; i < 9; i++) {
    const h = 12 + 20 * (0.5 + 0.5 * Math.sin(phase * 2 - i * 0.38));
    box(1552 + i * 16, 500 - h, 9, h, 3, i > 6 ? P.amber : P.pale);
  }

  // Substation housing, louvres and AC display are solid flat color fields.
  box(1389, 672, 30, 48, 7, P.navy);
  box(1405, 548, 330, 244, 22, P.white);
  box(1405, 548, 330, 58, 22, P.navy);
  box(1405, 583, 330, 23, 0, P.navy);
  text('GRID STATION', 1430, 586, 23, P.white, 'left', 700, 245);
  circle(1707, 577, 6, P.amber);
  box(1429, 629, 128, 92, 12, P.navy);
  text('AC', 1444, 652, 14, P.pale, 'left', 600, 38);
  ctx.save();
  roundedPath(1439, 661, 108, 46, 6);
  ctx.clip();
  waveBand(1440, 684, 106, 12, 5, phase * 5, 1.35, P.pale, false);
  ctx.restore();
  for (let col = 0; col < 6; col++) {
    box(1583 + col * 20, 633, 10, 30, 4, P.gray);
    box(1583 + col * 20, 676, 10, 30, 4, P.gray);
  }
  circle(1440, 753, 6, P.coral);
  text('GRID CONNECTED', 1459, 759, 17, P.navy, 'left', 600, 230);
  box(1433, 792, 48, 13, 4, P.navy);
  box(1659, 792, 48, 13, 4, P.navy);

  text('RENEWABLE DISTRIBUTION', 1570, 915, 21, P.navy, 'center', 700, 360);
  text('SHARED ENERGY NETWORK', 1570, 946, 15, P.navy, 'center', 500, 360);
  ctx.restore();
}
